<script lang="ts">
 import type {PageData} from './$types';import Title from '$lib/components/Title.svelte';import {formatMoney} from '$lib/utils';import PeriodPicker from '$lib/components/PeriodPicker.svelte';import Transactions from '$lib/components/ProductTransactions.svelte';
 let {data}:{data:PageData}=$props();const a=$derived(data.account);let q=$state('');const transactions=$derived(data.transactions.filter(t=>(t.merchant??'').toLowerCase().includes(q.toLowerCase())).toSorted((a,b)=>b.date.localeCompare(a.date)||b.id-a.id));
</script>
